<script setup lang="ts">
import { ref,watch } from 'vue'
import { Play,ArrowRight,CheckCircle2,XCircle,Copy } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import { getModelRoutes } from '../api/modelRoutes'
import { sendDemoRequest } from '../api/requests'
import { errorMessage } from '../api/http'
import type { ModelRoute,RequestRecord } from '../types'
const open=defineModel<boolean>({default:false}),routes=ref<ModelRoute[]>([]),model=ref(''),prompt=ref('请用简洁的语言介绍一下 ModelGate 的作用。'),simulateFailure=ref(false),loading=ref(false),error=ref(''),result=ref<{request:RequestRecord;answer:string}|null>(null)
watch(open,async value=>{if(value){error.value='';try{routes.value=await getModelRoutes();if(!model.value&&routes.value.length)model.value=routes.value[0]!.model}catch(e){error.value=errorMessage(e)}}})
async function send(){if(!model.value||!prompt.value.trim()){error.value='请选择模型并输入测试内容。';return}loading.value=true;error.value='';result.value=null;try{result.value=await sendDemoRequest({model:model.value,prompt:prompt.value.trim(),simulate_failure:simulateFailure.value,stream:false});window.dispatchEvent(new Event('modelgate:refresh'))}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function copy(){try{await navigator.clipboard.writeText('curl '+window.location.origin+'/v1/chat/completions \\\n  -H "Authorization: Bearer mg-demo-local" \\\n  -H "Content-Type: application/json" \\\n  -d \'{"model":"'+model.value+'","messages":[{"role":"user","content":"Hello"}]}\'');ElMessage.success('调用示例已复制')}catch{ElMessage.error('复制失败，请检查浏览器剪贴板权限')}}
</script>
<template><el-drawer v-model="open" title="测试模型请求" :size="580" class="test-drawer"><div class="drawer-intro"><span class="environment-badge">受控模拟上游</span><p>发起一次请求，观察模型选路和故障切换。不会访问外部模型服务。</p></div><form @submit.prevent="send"><label class="form-label">公开模型</label><el-select v-model="model" aria-label="公开模型" style="width:100%"><el-option v-for="route in routes" :key="route.id" :value="route.model" :label="route.model"/></el-select><label class="form-label space-top" for="test-prompt">测试内容</label><el-input id="test-prompt" v-model="prompt" type="textarea" :rows="4" maxlength="2000" show-word-limit placeholder="输入一条测试消息"/><div class="simulation-control"><div><strong>模拟首次上游失败</strong><p>首次尝试返回 503，观察备用上游接管。</p></div><el-switch v-model="simulateFailure" aria-label="模拟首次上游失败"/></div><div v-if="error" class="error-state" role="alert">{{error}}</div><div class="test-actions"><el-button type="primary" native-type="submit" :loading="loading" :disabled="!model"><Play v-if="!loading" :size="14"/>发送测试请求</el-button><button type="button" class="btn btn-quiet" @click="copy"><Copy :size="14"/>复制 cURL</button></div></form><section v-if="result" class="test-result"><div class="result-header"><component :is="result.request.status==='success'?CheckCircle2:XCircle" :size="18"/><strong>{{result.request.status==='success'?'请求已完成':'请求未完成'}}</strong><span class="mono muted">{{result.request.latency_ms}} ms</span></div><p class="request-answer">{{result.answer||result.request.error||'无可用响应'}}</p><h3 class="detail-section-title">路由追踪</h3><div v-for="(attempt,index) in result.request.attempts" :key="index" class="attempt-row"><span class="attempt-number">{{index+1}}</span><div><strong>{{attempt.provider}}</strong><span class="attempt-error">{{attempt.error||'响应成功'}}</span></div><span class="mono" :class="attempt.status_code>=400?'danger-text':'success-text'">{{attempt.status_code}}</span><span class="mono muted">{{attempt.latency_ms}} ms</span></div><p class="field-note mono">{{result.request.id}}</p><RouterLink class="text-link" to="/requests" @click="open=false">在请求日志中查看<ArrowRight :size="14"/></RouterLink></section></el-drawer></template>
